(3, 88, 'Cerebral Perfusion Pressure (CPP) is calculated as:', '["Mean Arterial Pressure minus Intracranial Pressure", "Systolic Blood Pressure plus Intracranial Pressure", "Heart Rate divided by Intracranial Pressure", "Diastolic Blood Pressure minus Heart Rate"]'::jsonb, 0),
(3, 89, 'What is the normal range for intracranial pressure (ICP) in adults?', '["0-5 mmHg", "20-30 mmHg", "30-40 mmHg", "5-15 mmHg"]'::jsonb, 3),
