(4, 6, 'Keratinocytes make up approximately what percentage of the epidermis?', '["50%", "75%", "95%", "100%"]'::jsonb, 2),
(4, 7, 'Urine passes through the renal collecting system in which correct sequence?', '["Minor calyx, major calyx, renal pelvis, ureter", "Major calyx, minor calyx, renal pelvis, ureter", "Renal pelvis, major calyx, minor calyx, ureter", "Minor calyx, renal pelvis, major calyx, ureter"]'::jsonb, 0),
(4, 8, 'Vital cardiorespiratory centres are located in the:', '["Cerebellum", "Medulla oblongata", "Occipital lobe", "Hypothalamus only"]'::jsonb, 1),
(4, 9, 'A rightward shift of the oxygen-haemoglobin dissociation curve is caused by:', '["Decreased temperature", "Increased 2,3-DPG, CO2, and temperature", "Decreased CO2", "Alkalosis"]'::jsonb, 1),
