(4, 95, 'Which statement about the unconscious patient is NOT correct?', '["Respiratory failure can cause unconsciousness", "Poor conscious levels are often accompanied by altered breathing patterns", "A saturation monitor provides all the information needed to assess respiratory function", "Airway protection is a nursing priority"]'::jsonb, 2),
(4, 96, 'Delirium Risk Factors are as follows EXCEPT', '["Obesity", "Preexisting dementia", "Bone fractures", "Infections"]'::jsonb, 0),
(4, 97, 'An effective nursing strategy to reduce ICU delirium includes:', '["Frequent changes of caregiving staff", "Reorientation using a clock, calendar, and family photos", "Keeping the environment brightly lit and noisy at all times", "Withholding explanations to avoid overstimulation"]'::jsonb, 1),
