-- CCN Exam Room: 7-day council-standard mock exams (200 questions a day, 1,400 in total), October 2026
-- Run this once in the Supabase SQL Editor. It is safe to run again.
--
-- All 1,400 questions are EXISTING questions from the app's question bank (no new questions are added).
-- Every day covers the full NMCN CCN curriculum in 4 sections of 50:
--   A Applied Sciences (Q1–50), B Fundamentals of CCN (Q51–100),
--   C Anaesthesia, Emergencies, O&G and Paediatrics (Q101–150), D Professional Practice (Q151–200).
-- Nothing from the Gombe papers is used, and no question appears on more than one day.
-- The Word documents (question papers, and answers with explanations) use the same numbering and answers.
--
-- What it does:
--   0. Adds the exam questions that were never loaded into the live database (see Step 0 below).
--   1. Finds each question in the bank (same wording, options and answer).
--   2. Creates 7 exams, "CCN Mock Exam — Day 1 of 7 (200 Questions)" to "Day 7 of 7", one a day from
--      Friday 23 Oct to Thursday 29 Oct 2026, 08:00–18:00 Nigeria time, 200 minutes per student,
--      answers hidden during the exam, score shown at the end. If an exam already exists, its questions
--      are replaced. Change the dates/times in the Exam Room admin page if needed, but do NOT press
--      "Pick random questions", or that day's questions will be replaced.
--   3. Renames the single exam made by the earlier version of this script ("CCN Council Mock Exam — 200 Questions") to Day 1,
--      and removes the 200 hidden questions the very first version added, if they exist.
--   4. Shows a check: each day should show 200 questions found and 200 in the exam.

-- Step 0: add the 133 exam questions that are in the app's question files but were never loaded into
-- the live database (CCN 412 Pre-Council questions and an AI practice batch). Questions already present
-- are skipped.
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by v.n),
       v.topic, v.source, v.q, v.opts, v.ans_idx, v.exp, v.category, v.category_icon, true
from (values
(1, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which nephron segment is primarily responsible for the countercurrent multiplier system that concentrates urine?', '["Bowman''s capsule", "Proximal convoluted tubule", "Renal pelvis", "Loop of Henle"]'::jsonb, 3, 'The descending and ascending limbs of the loop of Henle create a concentration gradient in the medullary interstitium via the countercurrent multiplier mechanism, enabling urine concentration.', 'Pre-Council', '🎓'),
(2, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which nursing intervention is most effective in preventing contrast-induced nephropathy in an at-risk patient before a CT scan with IV contrast?', '["Administering prophylactic antibiotics", "Withholding all oral fluids for 12 hours before the scan", "Administering a loop diuretic prior to the scan", "Ensuring adequate IV isotonic fluid hydration before and after the procedure"]'::jsonb, 3, 'Adequate periprocedural hydration with isotonic IV fluids is the most consistently effective measure to reduce the risk of contrast-induced nephropathy in at-risk patients.', 'Pre-Council', '🎓'),
(3, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A patient with severe emphysema is classically described as a ''pink puffer.'' This term reflects:', '["Cyanosis with peripheral oedema", "A thin body habitus, pursed-lip breathing, and relatively preserved oxygenation until late disease", "Obesity with cor pulmonale", "A productive cough with copious purulent sputum"]'::jsonb, 1, '''Pink puffers'' (emphysema-predominant COPD) tend to be thin and dyspneic with pursed-lip breathing, maintaining near-normal PaO2 longer by increasing ventilation, unlike ''blue bloaters.''', 'Pre-Council', '🎓'),
(4, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Type II (hypercapnic) respiratory failure is defined by:', '["A PaO2 less than 60 mmHg alone", "A PaCO2 greater than 50 mmHg with accompanying respiratory acidosis", "A normal PaCO2 with severe hypoxemia", "Elevated bicarbonate with normal pH"]'::jsonb, 1, 'Type II respiratory failure reflects ventilatory failure with inadequate CO2 elimination, defined by an elevated PaCO2 with acidemia, often from COPD exacerbation, neuromuscular weakness, or CNS depression.', 'Pre-Council', '🎓'),
(5, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A key clinical benefit of BiPAP in a patient with a COPD exacerbation and respiratory failure is that it:', '["Reduces the work of breathing by providing inspiratory pressure support while maintaining alveolar recruitment with EPAP", "Eliminates the need for any pharmacologic bronchodilator therapy", "Cures the underlying airway obstruction", "Requires no patient cooperation or spontaneous breathing effort"]'::jsonb, 0, 'The pressure differential in BiPAP, with IPAP greater than EPAP, assists the patient''s own inspiratory effort, reducing work of breathing, while EPAP prevents alveolar and airway collapse, helping avoid intubation in COPD exacerbations.', 'Pre-Council', '🎓'),
(6, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What PaO2/FiO2 ratio threshold, with PEEP of at least 5 cmH2O, defines severe ARDS under the Berlin definition?', '["300 or less", "200 or less", "100 or less", "150 or less"]'::jsonb, 2, 'Severe ARDS is defined as PaO2/FiO2 of 100 mmHg or less with PEEP at least 5 cmH2O; mild is 200-300 and moderate is 100-200.', 'Pre-Council', '🎓'),
(7, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A hemodialysis patient develops sudden hypotension, nausea, headache, and confusion approximately 3 hours into a first dialysis session. This presentation is most consistent with:', '["Anaphylaxis to the dialyzer membrane", "Air embolism", "Dialysis disequilibrium syndrome", "Hyperkalemic cardiac arrest"]'::jsonb, 2, 'Dialysis disequilibrium syndrome occurs when rapid removal of urea from the blood creates an osmotic gradient causing cerebral edema, most common during or after the first few dialysis sessions in patients with very high pre-dialysis BUN.', 'Pre-Council', '🎓'),
(8, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Hypothermia is a common complication of CRRT because:', '["CRRT machines actively cool the blood intentionally at all times", "Patients are typically febrile at baseline", "Extracorporeal blood is exposed to room-temperature tubing, filters, and replacement fluids, causing heat loss", "The dialysate is always heated above body temperature"]'::jsonb, 2, 'As blood circulates through extracorporeal tubing and filters and mixes with room-temperature replacement/dialysate fluids, significant heat loss occurs; most modern CRRT machines include blood-warming devices to mitigate this.', 'Pre-Council', '🎓'),
(9, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A patient opens their eyes only to painful stimuli, makes incomprehensible sounds, and withdraws from pain. What is the calculated GCS score?', '["6", "10", "12", "8"]'::jsonb, 3, 'Eye opening to pain = 2, incomprehensible sounds = 2, withdrawal from pain = 4; the total is 2+2+4 = 8.', 'Pre-Council', '🎓'),
(10, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Cushing''s triad, a late sign of rising intracranial pressure, consists of which three findings?', '["Hypotension, tachycardia, and tachypnea", "Hypertension with tachycardia and hyperthermia", "Hypertension with widened pulse pressure, bradycardia, and irregular respirations", "Hypotension, bradycardia, and apnea"]'::jsonb, 2, 'Cushing''s triad reflects the body''s attempt to maintain cerebral perfusion against rising ICP: widened pulse pressure hypertension, reflex bradycardia, and irregular respiratory patterns.', 'Pre-Council', '🎓'),
(11, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'The Kellie-Monro (Monro-Kellie) Doctrine states which of the following?', '["The skull is a rigid, non-expansile compartment; an increase in volume of one intracranial component requires a reciprocal decrease in another to keep ICP constant", "The brain can expand infinitely without pressure changes", "CSF volume is fixed and cannot change", "Cerebral blood flow is independent of ICP"]'::jsonb, 0, 'The Monro-Kellie doctrine describes the fixed, non-compliant cranial vault containing brain, blood, and CSF; a rise in one component''s volume must be offset by a decrease in another to keep ICP stable.', 'Pre-Council', '🎓'),
(12, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A Licox brain tissue oxygen monitor measures which of the following?', '["Brain tissue oxygen tension (PbtO2)", "Intracranial pressure only", "Cerebral blood flow velocity", "Serum oxygen saturation"]'::jsonb, 0, 'The Licox catheter is a direct brain tissue oxygen monitor that measures local PbtO2, providing information about cerebral oxygenation independent of systemic oxygen saturation.', 'Pre-Council', '🎓'),
(13, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Brudzinski''s sign is positive when which of the following occurs?', '["Pain on hip flexion with knee extension", "Involuntary flexion of the hips and knees when the examiner passively flexes the patient''s neck", "Dilation of the pupils with light exposure", "Rigid extension of the leg"]'::jsonb, 1, 'A positive Brudzinski''s sign occurs when passive neck flexion causes involuntary flexion of the hips and knees, reflecting meningeal irritation.', 'Pre-Council', '🎓'),
(14, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What are common initial presenting symptoms of Myasthenia Gravis?', '["Foot drop", "Urinary retention", "Severe headache", "Ptosis and diplopia"]'::jsonb, 3, 'Ocular symptoms such as ptosis (drooping eyelids) and diplopia (double vision) are the most common initial presentation of Myasthenia Gravis, reflecting early extraocular muscle involvement.', 'Pre-Council', '🎓'),
(15, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the first-line pharmacologic treatment for status epilepticus?', '["Oral phenytoin", "IV mannitol", "IV benzodiazepine (e.g., lorazepam)", "IV vancomycin"]'::jsonb, 2, 'IV benzodiazepines, such as lorazepam or diazepam, are the first-line agents for terminating status epilepticus due to their rapid onset of anticonvulsant action.', 'Pre-Council', '🎓'),
(16, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which sedative agent is preferred over benzodiazepines in mechanically ventilated ICU patients, in part due to its lower associated delirium risk?', '["Lorazepam", "Midazolam", "Dexmedetomidine", "Diazepam"]'::jsonb, 2, 'Dexmedetomidine, an alpha-2 agonist, is associated with a lower incidence of delirium compared with benzodiazepine sedation and is often preferred in mechanically ventilated patients.', 'Pre-Council', '🎓'),
(17, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'How is TENS distinguished from Stevens-Johnson Syndrome (SJS)?', '["Causative organism", "Percentage of body surface area with epidermal detachment (TEN greater than 30%, SJS less than 10%)", "Patient age only", "Presence of fever"]'::jsonb, 1, 'TENS and SJS exist on a spectrum of the same disease process, distinguished primarily by the percentage of body surface area with epidermal detachment: TEN affects greater than 30%, SJS less than 10%, with 10-30% classified as overlap.', 'Pre-Council', '🎓'),
(18, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'How is Toxic Epidermal Necrolysis Syndrome (TENS) best classified?', '["A severe, life-threatening mucocutaneous drug reaction with widespread epidermal detachment", "A viral exanthem", "A bacterial skin infection", "A chronic autoimmune skin condition unrelated to medications"]'::jsonb, 0, 'TENS is a rare but life-threatening mucocutaneous reaction, most often triggered by medications, characterized by widespread epidermal necrosis and detachment.', 'Pre-Council', '🎓'),
(19, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'When intubating a patient with suspected cervical spine injury, the recommended technique to protect the spine is:', '["Full neck extension for optimal glottic view", "Manual in-line stabilization with the anterior portion of the cervical collar removed during the procedure", "Flexion of the neck", "Leaving the patient fully upright"]'::jsonb, 1, 'The anterior portion of the collar is typically opened and an assistant maintains manual in-line stabilization to limit neck movement while allowing jaw manipulation for intubation.', 'Pre-Council', '🎓'),
(20, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'If a ventilated patient acutely desaturates and the cause is not immediately identified, an appropriate first-line nursing action while troubleshooting is to:', '["Leave the patient on the ventilator and wait", "Disconnect from the ventilator and manually ventilate with a bag-valve device on 100% oxygen while assessing for the cause", "Immediately extubate", "Turn off all alarms to focus"]'::jsonb, 1, 'Manually bagging with 100% oxygen while troubleshooting helps isolate whether the problem is with the ventilator or circuit versus the patient or airway, and ensures oxygen delivery during assessment.', 'Pre-Council', '🎓'),
(21, 'Disaster & Emergency Nursing', 'AI Practice Question', 'A hallmark early clinical clue suggesting necrotising fasciitis, distinguishing it from simple cellulitis, is:', '["Pain out of proportion to visible skin findings", "Mild, well-localised redness with minimal pain", "Slow onset over several weeks", "Complete absence of systemic symptoms"]'::jsonb, 0, 'Pain disproportionate to the apparent severity of skin findings is a classic early warning sign of necrotising fasciitis, prompting urgent surgical evaluation.', 'Infection Prevention', '🚨'),
(22, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Tracheo-oesophageal fistula is often associated with which other congenital anomaly?', '["Oesophageal atresia", "Cleft lip only", "Club foot only", "Polydactyly only"]'::jsonb, 0, 'Tracheo-oesophageal fistula commonly co-occurs with oesophageal atresia, and the combination requires prompt surgical correction.', 'Obstetric & Neonatal', '🤱'),
(23, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Pyloric stenosis in infants classically presents with:', '["Bilious vomiting from birth", "Projectile, non-bilious vomiting typically starting around 3–6 weeks of age", "Chronic diarrhoea", "Bloody stools with fever"]'::jsonb, 1, 'Hypertrophic pyloric stenosis classically causes projectile, non-bilious vomiting, usually presenting between 3–6 weeks of age.', 'GI, Endocrine & Metabolic', '🤱'),
(24, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Intussusception in infants classically presents with:', '["Painless abdominal distension only", "Episodic colicky abdominal pain, vomiting, and ''redcurrant jelly'' stools", "Chronic constipation with no acute symptoms", "A silent, asymptomatic abdominal mass"]'::jsonb, 1, 'Intussusception classically presents with episodic colicky pain, vomiting, and blood-stained ''redcurrant jelly'' stool as the bowel telescopes into itself.', 'GI, Endocrine & Metabolic', '🤱'),
(25, 'Paediatric Fluid & Dehydration (CCN 422)', 'AI Practice Question', 'Fluid therapy in a severely dehydrated child typically begins with:', '["Oral fluids only, regardless of severity", "A rapid IV fluid bolus for severe dehydration, followed by ongoing maintenance and deficit replacement", "Withholding all fluids until specialist review", "Only subcutaneous fluids"]'::jsonb, 1, 'Severe paediatric dehydration is managed with an initial rapid IV fluid bolus to restore circulating volume, followed by calculated maintenance and deficit replacement.', 'Renal & Fluid Balance', '🤱'),
(26, 'Paediatric Emergencies (CCN 422)', 'AI Practice Question', 'Febrile convulsions in young children are most commonly associated with:', '["A rapid rise in body temperature, often with a viral infection", "Chronic malnutrition alone", "Congenital heart disease exclusively", "Vitamin overdose"]'::jsonb, 0, 'Febrile convulsions typically occur with a rapid temperature rise in young children, often triggered by a common viral illness.', 'Neurology', '🤱'),
(27, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'Sudden Infant Death Syndrome (SIDS) risk is reduced by which key recommendation?', '["Placing infants to sleep prone (on their stomach)", "Placing infants to sleep supine (on their back)", "Co-sleeping in the same bed as an adult at all times", "Using soft, loose bedding in the crib"]'::jsonb, 1, 'The ''back to sleep'' recommendation — placing infants supine — is a key evidence-based measure shown to reduce SIDS risk.', 'Obstetric & Neonatal', '🤱'),
(28, 'Ethico-Legal Issues (CCN 424)', 'AI Practice Question', 'The Nursing and Midwifery Council of Nigeria (NMCN), as a professional regulatory body, is primarily responsible for:', '["Setting nursing education standards, registering/licensing nurses, and enforcing professional discipline", "Only organising nursing conferences", "Managing hospital construction budgets", "Setting national drug prices"]'::jsonb, 0, 'NMCN''s core functions include setting education/practice standards, registering and licensing nurses/midwives, and handling matters of professional discipline.', 'Ethics, Law & Management', '⚖️'),
(29, 'Applied Anatomy & Physiology (CCN 410) — Respiratory', 'AI Practice Question', 'Gaseous exchange in the lungs occurs primarily at the level of the:', '["Trachea", "Bronchi", "Alveoli", "Larynx"]'::jsonb, 2, 'The alveoli, with their thin walls and rich capillary network, are the site of gas exchange between air and blood.', 'Anatomy & Physiology', '🧬'),
(30, 'Applied Anatomy & Physiology (CCN 410) — Cardiovascular', 'AI Practice Question', 'The lymphatic system''s primary functions include all of the following EXCEPT:', '["Draining excess interstitial fluid back into the bloodstream", "Transporting absorbed dietary fats from the intestine", "Supporting immune function", "Directly pumping oxygenated blood to tissues"]'::jsonb, 3, 'Pumping oxygenated blood to tissues is the role of the cardiovascular system''s heart, not the lymphatic system, which drains fluid, transports fats, and supports immunity.', 'Anatomy & Physiology', '🧬'),
(31, 'Applied Anatomy & Physiology (CCN 410) — Central Nervous System', 'AI Practice Question', 'The spinal cord''s reflex action allows for:', '["Conscious decision-making before every movement", "A rapid, automatic response to a stimulus, bypassing the need for the brain to process it first", "Only sensory perception with no motor output", "Hormone regulation"]'::jsonb, 1, 'Spinal reflexes allow rapid, automatic responses (e.g. withdrawing a hand from a hot surface) via a reflex arc, without requiring conscious brain processing first.', 'Anatomy & Physiology', '🧬'),
(32, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A ventilated patient''s SpO2 drops from 96% to 88% acutely. Using a systematic differential for displacement, obstruction, pneumothorax, and equipment failure, the nurse should assess for all of these EXCEPT:', '["Tube displacement or dislodgement", "Airway obstruction from secretions", "Pneumothorax", "Recent oral care"]'::jsonb, 3, 'Recent oral care is not part of the differential for acute ventilator desaturation; the nurse should evaluate for tube displacement, obstruction, pneumothorax, and equipment or circuit failure.', 'Pre-Council', '🎓'),
(33, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Inhaled nitric oxide is used in pulmonary hypertensive crisis primarily because it:', '["Selectively dilates the pulmonary vasculature with minimal systemic hypotension", "Increases systemic vascular resistance", "Acts as a potent bronchoconstrictor", "Directly increases myocardial contractility"]'::jsonb, 0, 'Inhaled nitric oxide is delivered directly to ventilated alveoli, causing selective pulmonary vasodilation without significant systemic effects, useful in acute pulmonary hypertensive crises.', 'Pre-Council', '🎓'),
(34, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'The juxtaglomerular apparatus regulates blood pressure and renal blood flow chiefly by secreting which substance?', '["Antidiuretic hormone", "Aldosterone", "Renin", "Erythropoietin"]'::jsonb, 2, 'Juxtaglomerular cells release renin in response to reduced renal perfusion pressure or sympathetic stimulation, triggering the renin-angiotensin-aldosterone system.', 'Pre-Council', '🎓'),
(35, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which of the following is the most common intrinsic (intrarenal) cause of acute kidney injury in critically ill patients?', '["Bladder outlet obstruction", "Renal artery stenosis", "Nephrolithiasis", "Acute tubular necrosis"]'::jsonb, 3, 'Acute tubular necrosis, resulting from prolonged ischemia or nephrotoxin exposure, is the most common intrarenal cause of AKI in critically ill patients.', 'Pre-Council', '🎓'),
(36, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the first step in the pharmacologic management approach to ICU delirium?', '["Immediately start high-dose benzodiazepines", "Start antipsychotics for all patients regardless of cause", "Sedate to RASS -5 to prevent movement", "Identify and treat underlying reversible causes (pain, hypoxia, infection, metabolic derangement) before adding antipsychotics"]'::jsonb, 3, 'Effective delirium management begins with identifying and correcting reversible contributing causes, such as pain, hypoxia, infection, or metabolic derangement, before considering pharmacologic symptom control.', 'Pre-Council', '🎓'),
(37, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'The coup-contrecoup mechanism of brain injury describes which of the following?', '["Injury only at the site of direct impact", "Diffuse shearing injury without focal contusion", "Injury at the site of impact and at the opposite pole of the brain from movement within the skull", "A fracture line radiating from the impact point"]'::jsonb, 2, 'Coup injury occurs at the site of impact; contrecoup injury occurs at the opposite pole as the brain rebounds and strikes the skull, producing two areas of contusion.', 'Pre-Council', '🎓'),
(38, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which of the following is a preventable secondary brain injury factor that critical care nurses must aggressively manage after TBI?', '["The initial mechanical impact", "Skull fracture location", "Scalp laceration", "Hypotension and hypoxia"]'::jsonb, 3, 'Unlike the primary mechanical injury, hypotension and hypoxia are preventable secondary insults that significantly worsen neurologic outcomes and must be avoided.', 'Pre-Council', '🎓'),
(39, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What degree of head-of-bed elevation is recommended to reduce intracranial pressure while maintaining cerebral perfusion?', '["Flat at 0 degrees", "15 degrees of elevation", "30 degrees of elevation with neutral head and neck alignment", "90 degrees, fully upright"]'::jsonb, 2, 'Elevating the head of bed to about 30 degrees with the head in neutral alignment promotes cerebral venous drainage and lowers ICP without significantly compromising CPP.', 'Pre-Council', '🎓'),
(40, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which of the following findings is NOT compatible with a diagnosis of brain death?', '["Fixed and dilated pupils", "Absent corneal reflex", "Absent gag reflex", "Spontaneous respiratory effort during apnea testing"]'::jsonb, 3, 'Any spontaneous respiratory effort during a properly conducted apnea test indicates preserved brainstem respiratory drive and rules out brain death; the other findings are all expected in brain death.', 'Pre-Council', '🎓'),
(41, 'Anaesthesia (CCN 415) — Anaesthetic Gases', 'AI Practice Question', 'Indications for intubation in the critical care unit include all of the following EXCEPT:', '["Airway protection in a patient with reduced consciousness", "Respiratory failure requiring mechanical ventilation", "Anticipated airway compromise (e.g. severe burns/oedema)", "Mild, well-controlled hypertension"]'::jsonb, 3, 'Mild, well-controlled hypertension is not an indication for intubation — airway protection, respiratory failure, and anticipated airway compromise are recognised indications.', 'Respiratory', '💉'),
(42, 'Anaesthesia (CCN 415) — Ventilators', 'AI Practice Question', 'SIMV, as a mode of mechanical ventilation, stands for and allows:', '["Synchronized Intermittent Mandatory Ventilation — combines mandatory breaths with the ability for the patient to breathe spontaneously between them", "Simple Immediate Manual Ventilation — a purely manual bag-valve technique", "Static Inspiratory Muscle Ventilation — used only for muscle training", "Single Inflation Manual Volume — a one-time inflation mode"]'::jsonb, 0, 'SIMV (Synchronized Intermittent Mandatory Ventilation) delivers a set number of mandatory breaths synchronised with patient effort, while allowing spontaneous breaths in between.', 'Respiratory', '💉'),
(43, 'Anaesthesia (CCN 415) — Complications of Anaesthesia', 'AI Practice Question', 'Anaesthetic death investigations typically consider all of the following EXCEPT:', '["Adequacy of pre-anaesthetic assessment", "Appropriateness of drug selection and dosing", "Monitoring during the procedure", "The patient''s choice of hospital ward décor"]'::jsonb, 3, 'Ward décor is irrelevant to an anaesthetic death investigation — pre-assessment adequacy, drug management and intraoperative monitoring are the relevant factors reviewed.', 'Anaesthesia & Perioperative Care', '💉'),
(44, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Classic presenting features of appendicitis in a child include periumbilical pain migrating to which quadrant?', '["Right upper quadrant", "Left lower quadrant", "Right lower quadrant", "Left upper quadrant"]'::jsonb, 2, 'Appendicitis classically presents with pain that starts periumbilically and migrates to the right lower quadrant (McBurney''s point).', 'GI, Endocrine & Metabolic', '🤱'),
(45, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'Croup in a child is classically characterised by:', '["A high-pitched, barking cough with inspiratory stridor", "Silent chest with no cough", "Chronic productive cough over months", "Painless swallowing difficulty"]'::jsonb, 0, 'Croup (laryngotracheobronchitis) classically causes a barking cough and inspiratory stridor due to upper airway inflammation and narrowing.', 'Respiratory', '🤱'),
(46, 'Paediatric Fluid & Dehydration (CCN 422)', 'AI Practice Question', 'Assessing dehydration severity in a paediatric patient includes evaluating all of the following EXCEPT:', '["Skin turgor", "Mucous membrane moisture", "Urine output", "The child''s favourite toy"]'::jsonb, 3, 'Skin turgor, mucous membrane moisture, and urine output are all clinical indicators of hydration status; a child''s toy preference is irrelevant.', 'Renal & Fluid Balance', '🤱'),
(47, 'Applied Anatomy & Physiology (CCN 410) — Respiratory', 'AI Practice Question', 'Which structure connects the pharynx to the bronchi, serving as the main airway?', '["Oesophagus", "Trachea", "Aorta", "Ureter"]'::jsonb, 1, 'The trachea is the main airway connecting the larynx/pharynx above to the bronchi below, allowing air to pass to and from the lungs.', 'Anatomy & Physiology', '🧬'),
(48, 'Applied Anatomy & Physiology (CCN 410) — Integumentary & GIT', 'AI Practice Question', 'Gastrointestinal glandular secretions primarily aid in:', '["Chemical breakdown of food and enzymatic digestion", "Producing red blood cells", "Regulating body temperature exclusively", "Filtering blood"]'::jsonb, 0, 'GI glands (salivary, gastric, pancreatic, liver/bile) secrete enzymes and other substances essential for chemically breaking down food.', 'Anatomy & Physiology', '🧬'),
(49, 'Applied Anatomy & Physiology (CCN 410) — Renal', 'AI Practice Question', 'The functional unit of the kidney responsible for filtration is the:', '["Renal pelvis", "Nephron", "Ureter", "Bladder trigone"]'::jsonb, 1, 'The nephron, comprising the glomerulus and its associated tubules, is the kidney''s basic functional/filtering unit.', 'Anatomy & Physiology', '🧬'),
(50, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'The nurse assessing a ventilated patient should evaluate for signs of inadequate oxygenation or ventilation including all of the following EXCEPT:', '["Restlessness and confusion", "Tachycardia", "Bradycardia and hypotension as late signs", "Polyuria"]'::jsonb, 3, 'Polyuria is not a typical sign of hypoxemia or hypoventilation; restlessness, tachycardia, and eventually bradycardia and hypotension are recognized signs of worsening respiratory compromise.', 'Pre-Council', '🎓'),
(51, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A patient with acute pulmonary oedema on strict intake and output monitoring produces only 20 mL of urine in 2 hours despite IV furosemide 80 mg. What is the priority nursing action?', '["Administer another diuretic dose without further assessment", "Assess for hypotension and reassess renal perfusion, and notify the physician", "Increase IV fluids to promote diuresis", "Discontinue oxygen therapy"]'::jsonb, 1, 'Poor diuretic response may indicate inadequate renal perfusion (e.g., cardiogenic shock), requiring reassessment of hemodynamic status before further diuretic dosing.', 'Pre-Council', '🎓'),
(52, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which mechanism helps maintain glomerular filtration pressure when renal perfusion falls, mediated by angiotensin II?', '["Dilation of the efferent arteriole", "Dilation of both arterioles equally", "Constriction of the efferent arteriole", "Constriction of the afferent arteriole"]'::jsonb, 2, 'Angiotensin II preferentially constricts the efferent arteriole, raising intraglomerular pressure and helping preserve GFR during hypoperfusion; this is why ACE inhibitors/ARBs can precipitate AKI in volume depletion or renal artery stenosis.', 'Pre-Council', '🎓'),
(53, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Approximately what percentage of resting cardiac output do the kidneys normally receive?', '["40%", "5%", "10%", "20-25%"]'::jsonb, 3, 'The kidneys receive about one-fifth to one-quarter of cardiac output despite their small share of body weight, reflecting high metabolic and filtration demands.', 'Pre-Council', '🎓'),
(54, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A 68-year-old man with benign prostatic hyperplasia presents with anuria and a palpably distended bladder. This is most consistent with which category of AKI?', '["Prerenal", "Intrarenal", "Functional", "Postrenal"]'::jsonb, 3, 'Bladder outlet obstruction from BPH causes back-pressure on the kidneys and postrenal AKI; bladder decompression via catheterization often reverses it promptly.', 'Pre-Council', '🎓'),
(55, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'An unresponsive patient shows no abnormal movements, and continuous EEG shows a normal background without epileptiform activity. This clinical picture is best described as what?', '["An active tonic-clonic seizure", "Nonconvulsive status epilepticus", "A myoclonic seizure", "Unconsciousness/coma without seizure activity"]'::jsonb, 3, 'Unresponsiveness without abnormal movements and with a normal EEG background indicates coma or unconsciousness from a cause other than ongoing seizure activity.', 'Pre-Council', '🎓'),
(56, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which ICP monitoring device is considered the gold standard because it also allows therapeutic drainage of cerebrospinal fluid?', '["Subarachnoid bolt", "Epidural sensor", "Intraventricular catheter (external ventricular drain)", "Intraparenchymal fiberoptic monitor"]'::jsonb, 2, 'The intraventricular catheter (EVD) is the gold standard for ICP monitoring because, unlike bolts or parenchymal monitors, it also permits therapeutic CSF drainage to control ICP.', 'Pre-Council', '🎓'),
(57, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the normal range for intracranial pressure (ICP) in adults?', '["0-5 mmHg", "20-30 mmHg", "30-40 mmHg", "5-15 mmHg"]'::jsonb, 3, 'Normal adult ICP is approximately 5-15 mmHg; sustained values above 20 mmHg are generally treated as pathologically elevated.', 'Pre-Council', '🎓'),
(58, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Therapeutic hyperventilation used briefly as a temporizing measure for acute herniation should target a PaCO2 of approximately what value?', '["15-20 mmHg", "45-50 mmHg", "30-35 mmHg", "55-60 mmHg"]'::jsonb, 2, 'Brief hyperventilation to a PaCO2 of about 30-35 mmHg causes cerebral vasoconstriction to temporarily lower ICP; prolonged or more aggressive hyperventilation risks cerebral ischemia and is avoided.', 'Pre-Council', '🎓'),
(59, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A CSF leak is suspected from a patient''s nose after head trauma. Which bedside test helps confirm CSF rather than mucus?', '["Kernig''s sign", "Doll''s eye test", "Halo (ring) sign on gauze", "Babinski test"]'::jsonb, 2, 'When fluid containing CSF is dropped on gauze, CSF diffuses faster than blood, creating a clear halo/ring around a central blood spot; the fluid can also be confirmed positive for glucose.', 'Pre-Council', '🎓'),
(60, 'Anaesthesia (CCN 415) — Ventilators', 'AI Practice Question', 'Before caring for a patient on a mechanical ventilator, the nurse should be familiar with all of the following EXCEPT:', '["The ventilator mode and settings in use", "Alarm limits and troubleshooting", "The patient''s dietary preferences prior to admission", "Signs of a blocked or displaced endotracheal tube"]'::jsonb, 2, 'Ventilator type, settings, alarms and airway complication recognition are essential nursing knowledge; pre-admission dietary preference has no bearing on safe ventilator care.', 'Respiratory', '💉'),
(61, 'Anaesthesia (CCN 415) — Anaesthetic Gases', 'AI Practice Question', 'Hypercarbia during anaesthesia refers to:', '["Elevated blood carbon dioxide levels", "Low blood oxygen levels", "Elevated blood glucose", "Low blood pressure"]'::jsonb, 0, 'Hypercarbia is an abnormally elevated level of carbon dioxide in the blood, a recognised risk during inadequately monitored anaesthesia/ventilation.', 'Anaesthesia & Perioperative Care', '💉'),
(62, 'Anaesthesia (CCN 415) — Pulmonary Complications', 'AI Practice Question', 'A patient recovering from anaesthesia after a lung transplant requires particular nursing vigilance for:', '["Signs of rejection and pulmonary infection", "Only cardiac monitoring, with no respiratory focus", "Skin integrity exclusively", "Bowel function exclusively"]'::jsonb, 0, 'Post-transplant patients need close monitoring for graft rejection and infection, alongside standard post-anaesthetic respiratory and haemodynamic care.', 'Anaesthesia & Perioperative Care', '💉'),
(63, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Oesophageal atresia in a newborn classically presents with:', '["Normal feeding with no complications", "Excessive drooling, choking and coughing with feeding attempts", "Delayed passage of meconium only", "No respiratory symptoms at all"]'::jsonb, 1, 'Oesophageal atresia prevents the oesophagus from connecting normally to the stomach, causing drooling, choking and coughing when feeds are attempted.', 'Obstetric & Neonatal', '🤱'),
(64, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Hirschsprung''s disease is caused by:', '["Excess ganglion cells in the bowel wall", "Absence of ganglion cells in a segment of bowel, causing functional obstruction", "A viral infection of the colon", "An allergic reaction to milk protein"]'::jsonb, 1, 'Hirschsprung''s disease results from congenital absence of ganglion cells (aganglionosis) in a segment of bowel, preventing normal peristalsis and causing obstruction.', 'GI, Endocrine & Metabolic', '🤱'),
(65, 'Applied Anatomy & Physiology (CCN 410) — Integumentary & GIT', 'AI Practice Question', 'The skin''s appendages include all of the following EXCEPT:', '["Hair follicles", "Sweat glands", "Sebaceous glands", "Alveoli"]'::jsonb, 3, 'Alveoli are part of the respiratory system, not skin appendages — hair follicles, sweat glands and sebaceous glands are all skin appendages.', 'Anatomy & Physiology', '🧬'),
(66, 'Applied Anatomy & Physiology (CCN 410) — Respiratory', 'AI Practice Question', 'Residual volume is the amount of air:', '["Inhaled during a normal breath", "Exhaled forcefully after normal expiration", "Remaining in the lungs after maximal expiration", "Inhaled during maximal inspiration beyond tidal volume"]'::jsonb, 2, 'Residual volume is the air that remains in the lungs even after the most forceful expiration, preventing lung collapse.', 'Anatomy & Physiology', '🧬'),
(67, 'Applied Anatomy & Physiology (CCN 410) — Cardiovascular', 'AI Practice Question', 'The heart''s four chambers consist of:', '["Two atria and two ventricles", "Four ventricles only", "Four atria only", "One atrium and three ventricles"]'::jsonb, 0, 'The heart has two upper chambers (right and left atria) and two lower chambers (right and left ventricles).', 'Anatomy & Physiology', '🧬'),
(68, 'Applied Anatomy & Physiology (CCN 410) — Renal', 'AI Practice Question', 'The kidneys contribute to regulation of acid-base balance mainly by:', '["Producing insulin", "Excreting or reabsorbing hydrogen ions and bicarbonate", "Regulating heart rate", "Producing bile"]'::jsonb, 1, 'The kidneys help maintain acid-base balance by selectively excreting hydrogen ions and reabsorbing/regenerating bicarbonate.', 'Anatomy & Physiology', '🧬'),
(69, 'Laboratory Sciences (CCN 426)', 'AI Practice Question', 'Blood transfusion reactions can be classified broadly as:', '["Only immediate reactions exist; delayed reactions are not possible", "Immediate (e.g. acute haemolytic, allergic) and delayed (e.g. delayed haemolytic, iron overload) reactions", "Only allergic reactions occur", "Reactions cannot be classified in any meaningful way"]'::jsonb, 1, 'Transfusion reactions are classified into immediate reactions (occurring during/shortly after transfusion) and delayed reactions (occurring days to weeks later).', 'Laboratory Sciences & Haematology', '🔬'),
(70, 'Laboratory Sciences (CCN 426)', 'AI Practice Question', 'Haematological investigations typically assess:', '["Blood cell counts, haemoglobin, and coagulation parameters", "Only urine composition", "Only stool consistency", "Only skin pigmentation"]'::jsonb, 0, 'Haematological tests evaluate blood cell counts (red cells, white cells, platelets), haemoglobin, and coagulation status.', 'Laboratory Sciences & Haematology', '🔬'),
(71, 'Radiology (CCN 427)', 'AI Practice Question', 'On imaging of intestinal obstruction, distinguishing small bowel from large bowel obstruction is aided by which feature?', '["Small bowel loops show valvulae conniventes (complete transverse lines); large bowel shows haustra (incomplete lines)", "There is no radiological way to distinguish them", "Only CT can ever differentiate them, never plain X-ray", "Large bowel is always more centrally located regardless of distension"]'::jsonb, 0, 'Valvulae conniventes crossing the full width of small bowel loops versus the partial haustral markings of large bowel are classic plain-film differentiators.', 'Radiology & Imaging', '🩻'),
(72, 'Nursing Informatics & ICT', 'AI Practice Question', 'Random access file arrangement, compared to sequential access, allows:', '["Records to be accessed directly without reading through all preceding records", "Only reading records strictly in the order they were stored", "No possibility of updating individual records", "Access only during scheduled batch windows"]'::jsonb, 0, 'Random access allows direct retrieval of a specific record without sequentially reading through all prior records, unlike strictly sequential access.', 'Nursing Informatics & ICT', '💻'),
(73, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'All trauma patients undergoing emergency intubation should be treated as having a ''full stomach'' primarily because:', '["They have usually eaten recently", "Trauma, pain, and opioids delay gastric emptying, increasing aspiration risk", "It simplifies documentation", "It reduces the need for preoxygenation"]'::jsonb, 1, 'Trauma, stress, pain, and opioid analgesia delay gastric emptying; all trauma patients are assumed to have a full stomach, increasing aspiration risk during induction.', 'Pre-Council', '🎓'),
(74, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A patient with a haemothorax and hypovolemic shock requires which priority intervention alongside chest tube drainage?', '["Diuretic therapy", "Fluid resuscitation and blood product transfusion as indicated", "Immediate extubation", "Withholding IV access until surgery"]'::jsonb, 1, 'Significant blood loss requires prompt volume resuscitation, including crystalloids and blood products following massive transfusion protocols if needed, alongside source control via chest tube or surgery.', 'Pre-Council', '🎓'),
(75, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which mnemonic is commonly used to remember indications for urgent or emergent dialysis?', '["SEPSIS", "MONA", "AEIOU, standing for acidosis, electrolyte imbalance, ingestion/intoxication, overload, uremia", "FAST"]'::jsonb, 2, 'AEIOU summarizes classic emergent indications for dialysis: refractory metabolic Acidosis, severe Electrolyte abnormalities such as hyperkalemia, certain Ingestions/toxins, fluid Overload unresponsive to diuretics, and symptomatic Uremia.', 'Pre-Council', '🎓'),
(76, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which finding is most suggestive of contrast-induced nephropathy after coronary angiography?', '["Hyperkalemia occurring within minutes of injection", "Gross hematuria developing after two weeks", "Immediate anuria during the procedure", "Rise in serum creatinine within 24-72 hours of contrast exposure"]'::jsonb, 3, 'Contrast-induced nephropathy typically presents as a rise in serum creatinine within 24-72 hours after contrast administration, peaking around day 3-5, due to direct tubular toxicity and renal vasoconstriction.', 'Pre-Council', '🎓'),
(77, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A patient with severe hemorrhage and hypotension develops oliguria and rising creatinine. This mechanism of acute kidney injury is best classified as:', '["Nephrotoxic", "Postrenal", "Prerenal", "Intrarenal"]'::jsonb, 2, 'Hypovolemia and hypotension reduce renal perfusion without direct parenchymal damage initially, producing prerenal azotemia, which is reversible if perfusion is restored promptly.', 'Pre-Council', '🎓'),
(78, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the standard approach to bladder management for an unconscious patient?', '["No catheterization is needed for an unconscious patient", "Encouraging the patient to void on command", "Indwelling urinary catheter placement with strict intake and output monitoring", "Fluid restriction"]'::jsonb, 2, 'An unconscious patient cannot sense or control bladder function, so an indwelling catheter with strict I&O monitoring is used to manage urinary elimination and track fluid balance.', 'Pre-Council', '🎓'),
(79, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the recommended external anatomical reference point used to zero and level an external ventricular drain (EVD)?', '["Xiphoid process", "Umbilicus", "Sternal angle", "Tragus of the ear (level of the foramen of Monro)"]'::jsonb, 3, 'The tragus approximates the level of the foramen of Monro and is the standard external reference point for zeroing and leveling an EVD transducer or drainage chamber.', 'Pre-Council', '🎓'),
(80, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A Glasgow Coma Scale score in which range classifies a traumatic brain injury as severe?', '["13-15", "9-12", "3-8", "3-5 only"]'::jsonb, 2, 'A GCS of 3-8 defines severe traumatic brain injury and is the threshold commonly used to indicate the need for airway protection/intubation.', 'Pre-Council', '🎓'),
(81, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the priority nursing intervention for airway management in an unconscious patient?', '["Position the patient supine and flat", "Insert an oral airway only if the gag reflex is present", "Elevate the legs above the level of the heart", "Position the patient laterally (recovery position) or semi-prone with the head of bed elevated to maintain a patent airway"]'::jsonb, 3, 'Lateral or semi-prone positioning with head-of-bed elevation prevents the tongue from occluding the airway and reduces aspiration risk in an unconscious patient who cannot protect their own airway.', 'Pre-Council', '🎓'),
(82, 'Anaesthesia (CCN 415) — Anaesthetic Gases', 'AI Practice Question', 'Hypoxia during general anaesthesia refers to:', '["Inadequate oxygen delivery to tissues", "Excess oxygen delivery to tissues", "Elevated body temperature", "Low blood glucose"]'::jsonb, 0, 'Hypoxia is inadequate tissue oxygenation, a critical complication to detect and correct promptly during anaesthesia.', 'Anaesthesia & Perioperative Care', '💉'),
(83, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'Severe neonatal jaundice is primarily concerning because untreated high bilirubin levels can cause:', '["No lasting harm regardless of level", "Kernicterus (bilirubin-induced brain damage)", "Improved neurological development", "Only mild, temporary skin discolouration with no other risk"]'::jsonb, 1, 'Untreated severe hyperbilirubinaemia can cross the blood-brain barrier and cause kernicterus, a form of permanent brain damage — hence the urgency of treatment (phototherapy/exchange transfusion).', 'Obstetric & Neonatal', '🤱'),
(84, 'Management & Teaching (GST 420)', 'AI Practice Question', 'A nurse manager reviewing a department''s risk management programme should ensure it includes:', '["Common risk categories, elements of risk management, and a functioning incident reporting system", "Only a list of staff names", "No formal documentation, to save time", "A focus solely on financial risk, excluding patient safety risk"]'::jsonb, 0, 'An effective departmental risk management programme addresses relevant risk categories, applies core risk management elements, and relies on functioning incident reporting.', 'Ethics, Law & Management', '⚖️'),
(85, 'Applied Anatomy & Physiology (CCN 410) — Respiratory', 'AI Practice Question', 'Which factor does NOT directly affect the rate or depth of respiration?', '["Blood CO2 levels", "Blood pH", "Blood glucose level", "Blood O2 levels"]'::jsonb, 2, 'Respiration is primarily regulated by chemoreceptors sensing CO2, pH and O2 levels — blood glucose has no direct regulatory role in respiratory drive.', 'Anatomy & Physiology', '🧬'),
(86, 'Applied Anatomy & Physiology (CCN 410) — Integumentary & GIT', 'AI Practice Question', 'Absorption of digested nutrients occurs primarily in the:', '["Stomach", "Oesophagus", "Small intestine", "Large intestine"]'::jsonb, 2, 'The small intestine, with its large surface area from villi and microvilli, is the primary site of nutrient absorption.', 'Anatomy & Physiology', '🧬'),
(87, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'After needle decompression for tension pneumothorax, the nurse should anticipate which next intervention?', '["Immediate discharge planning", "Chest tube (tube thoracostomy) insertion for definitive management", "Discontinuation of oxygen therapy", "Administration of thrombolytics"]'::jsonb, 1, 'Needle decompression is a temporizing measure; definitive management requires chest tube placement to allow continuous evacuation of air and lung re-expansion.', 'Pre-Council', '🎓'),
(88, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which pharmacologic agent may be used early in severe ARDS to improve ventilator synchrony and reduce oxygen consumption?', '["A neuromuscular blocking agent such as cisatracurium", "A loop diuretic", "A beta-agonist bronchodilator", "A systemic anticoagulant"]'::jsonb, 0, 'Short-term neuromuscular blockade in early severe ARDS can improve patient-ventilator synchrony, reduce barotrauma, and decrease oxygen consumption and CO2 production.', 'Pre-Council', '🎓'),
(89, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A hemodialysis patient reports muscle cramps during the latter part of a dialysis session. This is most often related to:', '["Excessive potassium removal", "Hyperglycemia", "Excess dialysate temperature", "Rapid fluid/electrolyte shifts and relative hypovolemia from aggressive ultrafiltration"]'::jsonb, 3, 'Intradialytic muscle cramps are commonly linked to rapid fluid removal, hypovolemia, and electrolyte shifts, particularly sodium and calcium; slowing the ultrafiltration rate and adjusting dialysate sodium often help.', 'Pre-Council', '🎓'),
(90, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which laboratory pattern is most consistent with prerenal azotemia rather than intrinsic renal failure?', '["FENa greater than 2%", "BUN:creatinine ratio near 10:1 with dilute urine", "Urine sodium greater than 40 mEq/L", "BUN:creatinine ratio greater than 20:1 with concentrated urine"]'::jsonb, 3, 'In prerenal azotemia, the kidney avidly reabsorbs sodium and water, producing a BUN:creatinine ratio greater than 20:1, concentrated urine, low urine sodium, and FENa less than 1%.', 'Pre-Council', '🎓'),
(91, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Abnormal flexion (decorticate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["3", "6", "5", "4"]'::jsonb, 0, 'Decorticate (abnormal flexor) posturing is scored as a motor response of 3 on the GCS, worse than localizing (5) or withdrawal (4) but better than extensor posturing (2).', 'Pre-Council', '🎓'),
(92, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A positive Babinski response (dorsiflexion of the great toe with fanning of the other toes) is considered a normal finding in which population?', '["Healthy adults", "Elderly patients only", "Infants under approximately 1-2 years of age", "Post-exercise adults"]'::jsonb, 2, 'An extensor plantar (Babinski) response is a normal finding in infants due to incomplete corticospinal tract myelination and becomes abnormal once the tract matures, typically by age 1-2 years.', 'Pre-Council', '🎓'),
(93, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which is an appropriate DVT prophylaxis strategy for an immobile, unconscious neurologic patient without contraindications?', '["Strict bed rest without any prophylaxis", "Early ambulation only", "Keeping the head of bed flat continuously", "Sequential compression devices and/or pharmacologic prophylaxis"]'::jsonb, 3, 'Since the patient cannot ambulate, mechanical (sequential compression devices) and, when appropriate, pharmacologic prophylaxis are used to reduce venous thromboembolism risk.', 'Pre-Council', '🎓'),
(94, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'During cold caloric (oculovestibular) testing, which finding is consistent with brain death?', '["A normal brainstem shows no eye movement to cold water irrigation", "The test evaluates the pupillary light reflex, not eye movement", "Absence of eye deviation toward the irrigated ear indicates loss of the oculovestibular reflex, consistent with brain death", "The test evaluates spinal cord reflexes only"]'::jsonb, 2, 'In an intact brainstem, cold water irrigation of the ear causes tonic eye deviation toward that ear; absence of this response indicates loss of brainstem function consistent with brain death.', 'Pre-Council', '🎓'),
(95, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which findings indicate impending respiratory failure in a patient with Guillain-Barre syndrome, warranting intubation?', '["Vital capacity greater than 60 mL/kg", "NIF more negative than -80 cmH2O", "Vital capacity less than 15-20 mL/kg or NIF less negative than -20 to -25 cmH2O", "A respiratory rate of 14 breaths/min"]'::jsonb, 2, 'A falling vital capacity below approximately 15-20 mL/kg or an NIF that is less negative than -20 to -25 cmH2O signals significant respiratory muscle weakness requiring elective intubation before crisis develops.', 'Pre-Council', '🎓'),
(96, 'Anaesthesia (CCN 415) — Anaesthetic Gases', 'AI Practice Question', 'Central venous pressure (CVP) measurement during anaesthesia primarily provides information about:', '["Arterial oxygen saturation", "Right heart filling pressure/venous return, useful for guiding fluid management", "Airway resistance", "Blood glucose level"]'::jsonb, 1, 'CVP reflects right atrial/venous filling pressure and is used to help guide fluid administration and assess volume status.', 'Anaesthesia & Perioperative Care', '💉'),
(97, 'Disaster & Emergency Nursing', 'AI Practice Question', 'An intra-ventricular pressure monitor is used to measure:', '["Cardiac output only", "Intracranial pressure via a catheter placed in the brain''s ventricular system", "Blood glucose", "Peripheral oxygen saturation"]'::jsonb, 1, 'An intraventricular catheter directly measures intracranial pressure, providing precise ICP monitoring in patients with severe brain injury.', 'Neurology', '🚨'),
(98, 'Paediatric Haematology (CCN 422)', 'AI Practice Question', 'Childhood leukaemia is best broadly described as:', '["A localised bone infection", "A malignancy of white blood cell precursors, disrupting normal blood cell production", "A disorder limited to red blood cells", "A benign, self-limiting skin condition"]'::jsonb, 1, 'Leukaemia is a haematological malignancy arising from abnormal proliferation of white blood cell precursors, which can crowd out normal blood cell production.', 'Laboratory Sciences & Haematology', '🤱'),
(99, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'Epiglottitis in a child is a medical emergency mainly because of the risk of:', '["Mild sore throat only", "Rapid, complete airway obstruction", "Chronic hoarseness", "Ear infection"]'::jsonb, 1, 'Epiglottitis causes rapid swelling that can completely obstruct the airway, making it a critical emergency requiring careful, minimal-intervention airway management.', 'Respiratory', '🤱'),
(100, 'Applied Anatomy & Physiology (CCN 410) — Endocrine', 'AI Practice Question', 'Endocrine glands differ from exocrine glands in that endocrine glands:', '["Secrete hormones directly into the bloodstream, with no ducts", "Always secrete through a duct onto an epithelial surface", "Never produce chemical messengers", "Only function during childhood"]'::jsonb, 0, 'Endocrine glands are ductless — they release hormones directly into the bloodstream, unlike exocrine glands which secrete via ducts.', 'Anatomy & Physiology', '🧬'),
(101, 'Applied Anatomy & Physiology (CCN 410) — Cardiovascular', 'AI Practice Question', 'Platelets (thrombocytes) primarily function in:', '["Oxygen transport", "Blood clotting/haemostasis", "Fighting bacterial infection", "Producing hormones"]'::jsonb, 1, 'Platelets are essential for haemostasis, aggregating at sites of vessel injury to help form a clot.', 'Anatomy & Physiology', '🧬'),
(102, 'Applied Anatomy & Physiology (CCN 410) — Respiratory', 'AI Practice Question', 'Total lung capacity is best defined as:', '["The volume of air moved in a single normal breath", "The maximum volume of air the lungs can hold after maximal inspiration", "The volume remaining in the lungs after maximal expiration", "The volume exhaled in the first second of forced expiration"]'::jsonb, 1, 'Total lung capacity is the maximum volume of air the lungs can contain after a maximal inspiratory effort.', 'Anatomy & Physiology', '🧬'),
(103, 'Applied Pharmacology (CCN 414)', 'AI Practice Question', 'Drug overdose management in the critical care unit generally follows which sequence of priorities?', '["Airway/breathing/circulation support first, then specific decontamination/antidote measures where appropriate", "Antidote administration only, with no attention to airway/breathing/circulation", "Discharge planning first, before any stabilisation", "Ignoring vital signs until toxicology results return"]'::jsonb, 0, 'Overdose management always prioritises ABC stabilisation first, followed by specific decontamination (e.g. activated charcoal) or antidote administration where indicated.', 'ICU Pharmacology', '💊'),
(104, 'Pulmonary Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'In a retained haemothorax not resolving with standard chest tube drainage, which intervention may be indicated?', '["Video-assisted thoracoscopic surgery (VATS) for evacuation of clotted blood", "Increased oral fluid intake", "Nebulized bronchodilators", "Discontinuation of the chest tube without further evaluation"]'::jsonb, 0, 'VATS allows direct visualization and evacuation of retained clotted blood that a standard chest tube cannot adequately drain, preventing complications like fibrothorax or empyema.', 'Pre-Council', '🎓'),
(105, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'In ARDS lung-protective ventilation, plateau pressure should be maintained at or below:', '["40 cmH2O", "35 cmH2O", "30 cmH2O", "25 cmH2O"]'::jsonb, 2, 'Keeping plateau pressure at 30 cmH2O or less limits alveolar overdistension and reduces the risk of barotrauma.', 'Pre-Council', '🎓'),
(106, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which finding in the immediate postoperative period after nephrectomy should be reported to the surgeon promptly as a possible sign of hemorrhage?', '["Urine output of 40 mL/hr", "Normal bowel sounds returning on postoperative day 2", "Mild incisional pain controlled by prescribed analgesia", "Increasing abdominal/flank distention, tachycardia, and dropping blood pressure"]'::jsonb, 3, 'Increasing flank or abdominal distention combined with tachycardia and hypotension are classic signs of internal hemorrhage and require immediate notification of the surgical team.', 'Pre-Council', '🎓'),
(107, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which structure is the primary site of blood filtration in the nephron?', '["Distal convoluted tubule", "Collecting duct", "Glomerulus", "Loop of Henle"]'::jsonb, 2, 'The glomerulus is a tuft of capillaries where plasma is filtered under pressure into Bowman''s capsule, forming the filtrate that becomes urine.', 'Pre-Council', '🎓'),
(108, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Cardiorenal syndrome in a patient with acute decompensated heart failure is best explained by which pathophysiology?', '["Autoimmune injury to the glomerular basement membrane", "Direct nephrotoxicity from cardiac medications", "Ureteral compression by an enlarged heart", "Reduced cardiac output and venous congestion impairing renal perfusion and function"]'::jsonb, 3, 'Cardiorenal syndrome results from reduced forward cardiac output combined with elevated central venous pressure causing renal venous congestion, both of which impair glomerular filtration.', 'Pre-Council', '🎓'),
(109, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'How does the Tensilon (edrophonium) test differentiate myasthenic crisis from cholinergic crisis?', '["It has an identical effect in both crises", "It only diagnoses cholinergic crisis", "It has no clinical utility in crisis differentiation", "It improves weakness in myasthenic crisis but worsens weakness in cholinergic crisis"]'::jsonb, 3, 'Because edrophonium is itself a cholinesterase inhibitor, it transiently improves strength in myasthenic crisis (too little acetylcholine effect) but worsens weakness in cholinergic crisis (already excessive acetylcholine effect).', 'Pre-Council', '🎓'),
(110, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the standard time window from symptom onset for administering IV tissue plasminogen activator (tPA) in acute ischemic stroke?', '["12 hours", "24 hours", "3-4.5 hours", "48 hours"]'::jsonb, 2, 'IV tPA is generally administered within 3 to 4.5 hours of clearly defined symptom onset in eligible patients, based on established stroke treatment protocols.', 'Pre-Council', '🎓'),
(111, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which additional NANDA nursing diagnosis is applicable to a delirious patient at risk of self-extubation or falls?', '["Impaired Urinary Elimination", "Deficient Knowledge", "Sexual Dysfunction", "Risk for Injury"]'::jsonb, 3, 'Delirious patients with impaired judgment and attention are at increased risk for self-harm, such as accidental self-extubation or falls, making Risk for Injury an appropriate diagnosis.', 'Pre-Council', '🎓'),
(112, 'Anaesthesia (CCN 415) — Pulmonary Complications', 'AI Practice Question', 'Mendelson''s Syndrome refers to:', '["A cardiac arrhythmia occurring during anaesthesia", "Chemical pneumonitis from aspiration of gastric contents during anaesthesia", "A type of anaesthetic overdose", "A skin reaction to anaesthetic gas"]'::jsonb, 1, 'Mendelson''s Syndrome is aspiration pneumonitis resulting from inhalation of acidic gastric contents, a recognised anaesthetic complication.', 'Anaesthesia & Perioperative Care', '💉'),
(113, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'An incarcerated inguinal hernia in an infant requires:', '["No urgent action, since it will resolve spontaneously", "Urgent medical assessment, as it risks bowel strangulation/ischaemia", "Only outpatient follow-up in a few months", "Treatment with laxatives"]'::jsonb, 1, 'An incarcerated hernia risks strangulation of the bowel with resulting ischaemia, making it a surgical emergency requiring urgent assessment.', 'GI, Endocrine & Metabolic', '🤱'),
(114, 'Paediatric Haematology (CCN 422)', 'AI Practice Question', 'Sickle cell crisis in a child is typically managed with:', '["Fluid restriction and cold application", "Hydration, analgesia, oxygen, and treatment of any precipitating factor (e.g. infection)", "Immediate blood transfusion in every case regardless of severity", "Strict bed rest with no other intervention"]'::jsonb, 1, 'Sickle cell crisis management centres on hydration, effective analgesia, oxygen therapy, and treating any underlying trigger such as infection.', 'Laboratory Sciences & Haematology', '🤱'),
(115, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'Neonatal sepsis should be suspected in a newborn presenting with:', '["Only a normal temperature with no other findings", "Non-specific signs such as poor feeding, temperature instability, lethargy, or respiratory distress", "Only visible jaundice, with no other clue needed", "Normal activity and feeding with no concerning signs"]'::jsonb, 1, 'Neonatal sepsis often presents with non-specific signs — poor feeding, temperature instability, lethargy or respiratory distress — requiring a high index of suspicion.', 'Obstetric & Neonatal', '🤱'),
(116, 'Applied Anatomy & Physiology (CCN 410) — Renal', 'AI Practice Question', 'The counter-current mechanism in the kidney is primarily involved in:', '["Producing red blood cells", "Concentrating or diluting urine to regulate body fluid balance", "Filtering large proteins out of the blood", "Regulating blood pH exclusively via the lungs"]'::jsonb, 1, 'The counter-current multiplier/exchange system in the loop of Henle and vasa recta allows the kidney to concentrate or dilute urine, regulating body water balance.', 'Anatomy & Physiology', '🧬'),
(117, 'Applied Anatomy & Physiology (CCN 410) — Cardiovascular', 'AI Practice Question', 'The primary function of red blood cells is to:', '["Fight infection", "Transport oxygen and carbon dioxide", "Form blood clots", "Produce antibodies"]'::jsonb, 1, 'Red blood cells, via haemoglobin, transport oxygen from the lungs to tissues and help carry carbon dioxide back to the lungs.', 'Anatomy & Physiology', '🧬'),
(118, 'Applied Anatomy & Physiology (CCN 410) — Integumentary & GIT', 'AI Practice Question', 'Which gastrointestinal process refers to the physical and chemical breakdown of food into absorbable units?', '["Absorption", "Digestion", "Transportation", "Excretion"]'::jsonb, 1, 'Digestion is the breakdown of food (mechanically and chemically) into smaller, absorbable molecules.', 'Anatomy & Physiology', '🧬'),
(119, 'Applied Anatomy & Physiology (CCN 410) — Endocrine', 'AI Practice Question', 'Hormonal control of a target organ commonly occurs through:', '["Direct nerve stimulation only, with no chemical signal", "Hormones binding to specific receptors on or in target cells", "Physical contact between glands and organs", "Muscle contraction alone"]'::jsonb, 1, 'Hormones exert their effects by binding to specific receptors on or within target cells, triggering a physiological response.', 'Anatomy & Physiology', '🧬'),
(120, 'Laboratory Sciences (CCN 426)', 'AI Practice Question', 'Biochemical laboratory investigations in critical care commonly include measurement of:', '["Electrolytes, renal and liver function tests", "Only bone density", "Only visual acuity", "Only hearing thresholds"]'::jsonb, 0, 'Biochemical investigations commonly assess electrolytes, renal function (urea/creatinine) and liver function — key parameters for monitoring critically ill patients.', 'Laboratory Sciences & Haematology', '🔬'),
(121, 'Management of Patients with Respiratory Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which mode of ventilation would be least appropriate as the sole mode for an apneic, heavily sedated patient with no spontaneous respiratory effort?', '["Assist-Control", "Pressure Control Ventilation", "CPAP with pressure support alone and no backup mandatory rate", "SIMV with an adequate mandatory rate"]'::jsonb, 2, 'CPAP or pressure support without a backup mandatory rate relies on the patient''s spontaneous effort to trigger breaths; an apneic patient would receive no ventilation, risking respiratory arrest.', 'Pre-Council', '🎓'),
(122, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'A normal BUN:creatinine ratio is approximately:', '["5:1", "30:1 to 40:1", "50:1", "10:1 to 20:1"]'::jsonb, 3, 'The normal BUN:creatinine ratio is roughly 10:1 to 20:1; ratios above 20:1 suggest a prerenal cause such as dehydration or GI bleeding.', 'Pre-Council', '🎓'),
(123, 'Renal Disorders', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Renal autoregulation maintains a relatively constant glomerular filtration rate across which approximate range of mean arterial pressure?', '["60-80 mmHg", "40-60 mmHg", "180-220 mmHg", "80-180 mmHg"]'::jsonb, 3, 'Through myogenic and tubuloglomerular feedback mechanisms, renal blood flow and GFR remain relatively stable across a MAP range of roughly 80-180 mmHg; below this, renal perfusion falls sharply.', 'Pre-Council', '🎓'),
(124, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Diminished or absent deep tendon reflexes are a classic finding in which condition covered in this unit?', '["Guillain-Barre syndrome", "Simple febrile seizure", "Toxic epidermal necrolysis syndrome", "Migraine"]'::jsonb, 0, 'Guillain-Barre syndrome is an acute inflammatory demyelinating polyneuropathy that classically presents with progressive weakness accompanied by diminished or absent deep tendon reflexes (areflexia).', 'Pre-Council', '🎓'),
(125, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'How is verbal responsiveness typically documented on the GCS for an intubated patient who cannot speak?', '["The GCS is omitted entirely", "A verbal score of 5 is assigned automatically", "The motor score alone is used as the total", "A verbal score of 1 is assigned with a \"T\" suffix noting intubation"]'::jsonb, 3, 'Because an intubated patient cannot produce verbal sounds, the verbal component is typically scored as 1 and documented with a "T" (e.g., "GCS 10T") to indicate the limitation.', 'Pre-Council', '🎓'),
(126, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'What is the priority nursing action for a patient with suspected CSF rhinorrhea after head trauma?', '["Insert a nasogastric tube for feeding", "Position the patient supine and flat", "Encourage vigorous coughing", "Avoid nose blowing, suctioning, and nasal packing"]'::jsonb, 3, 'Nasal suctioning, blowing, or packing can introduce pathogens through the dural tear and raise the risk of ascending meningitis, so these are avoided until the leak resolves or is repaired.', 'Pre-Council', '🎓'),
(127, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'On the standard deep tendon reflex grading scale, a score of 4+ indicates which finding?', '["Absent reflex", "Normal reflex", "Diminished reflex", "Brisk, hyperactive reflex with clonus"]'::jsonb, 3, 'The DTR scale ranges from 0 (absent) to 4+ (brisk/hyperactive with clonus), with 2+ representing a normal response.', 'Pre-Council', '🎓'),
(128, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'Which activities represent appropriate cognitive stimulation for delirium prevention?', '["Complete sensory deprivation", "Prolonged isolation", "Orientation boards, clocks/calendars, and engaging conversation", "Continuous television without interaction"]'::jsonb, 2, 'Providing orientation boards, visible clocks and calendars, and engaging in meaningful conversation helps maintain cognitive stimulation and orientation, reducing delirium risk.', 'Pre-Council', '🎓'),
(129, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'In select patients with large vessel occlusion ischemic stroke and favorable imaging, mechanical thrombectomy may be performed up to how many hours from symptom onset?', '["6 hours only", "72 hours", "Up to 24 hours in select patients with favorable imaging", "1 hour only"]'::jsonb, 2, 'With advanced perfusion imaging selection, mechanical thrombectomy for large vessel occlusion can be extended up to 24 hours in carefully selected patients.', 'Pre-Council', '🎓'),
(130, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'During a formal apnea test, which finding supports a diagnosis of brain death?', '["The patient takes one deep breath", "PaCO2 falls below 30 mmHg", "The patient coughs during suctioning", "PaCO2 rises above 60 mmHg (or 20 mmHg above baseline) without spontaneous respiratory effort"]'::jsonb, 3, 'A positive apnea test, supporting brain death, occurs when the PaCO2 rises sufficiently to strongly stimulate respiratory drive yet the patient shows no spontaneous respiratory effort.', 'Pre-Council', '🎓'),
(131, 'Neurology', 'CCN Curriculum — Fundamentals of Critical Care Nursing I', 'The National Institutes of Health Stroke Scale (NIHSS) is used clinically to accomplish which of the following?', '["Measure intracranial pressure directly", "Diagnose brain death", "Quantify stroke severity and neurological deficit", "Grade delirium severity"]'::jsonb, 2, 'The NIHSS is a standardized, validated tool used to quantify the severity of neurological deficits in acute stroke and to track changes over time.', 'Pre-Council', '🎓'),
(132, 'Paediatric Surgical Emergencies (CCN 422)', 'AI Practice Question', 'Malrotation with volvulus in an infant is a surgical emergency mainly because it can cause:', '["Mild, self-limiting abdominal discomfort", "Bowel ischaemia from twisting of the mesentery, risking bowel necrosis", "Only skin rash", "Chronic mild constipation"]'::jsonb, 1, 'Volvulus twists the bowel and its mesentery, cutting off blood supply and risking rapid bowel ischaemia/necrosis if not surgically corrected urgently.', 'GI, Endocrine & Metabolic', '🤱'),
(133, 'Paediatric Medical Emergencies (CCN 422)', 'AI Practice Question', 'A child presenting with epiglottitis should generally be managed by:', '["Immediately examining the throat with a tongue depressor", "Avoiding upsetting/examining the throat unnecessarily and urgently involving anaesthesia/ENT for controlled airway management", "Sending the child home with oral antibiotics", "Encouraging the child to lie flat immediately"]'::jsonb, 1, 'Throat examination or upsetting a child with suspected epiglottitis can precipitate complete airway obstruction — urgent, controlled airway management by experienced teams is essential.', 'Respiratory', '🤱')
) as v(n, topic, source, q, opts, ans_idx, exp, category, category_icon)
where not exists (
  select 1 from public.questions x
  where regexp_replace(lower(x.q), '[^a-z0-9]', '', 'g') = regexp_replace(lower(v.q), '[^a-z0-9]', '', 'g')
    and x.opts = v.opts and x.ans_idx = v.ans_idx
);

drop table if exists mock7;
create temporary table mock7 (day int, n int, q text, opts jsonb, ans_idx int, id int, primary key (day, n));

update mock7 m set id = (
  select min(x.id) from public.questions x
  where regexp_replace(lower(x.q), '[^a-z0-9]', '', 'g') = regexp_replace(lower(m.q), '[^a-z0-9]', '', 'g')
    and x.opts = m.opts and x.ans_idx = m.ans_idx
);

update public.exam_exams set title = 'CCN Mock Exam — Day 1 of 7 (200 Questions)'
 where title = 'CCN Council Mock Exam — 200 Questions'
   and not exists (select 1 from public.exam_exams where title = 'CCN Mock Exam — Day 1 of 7 (200 Questions)');

update public.exam_exams set question_ids = (select array_agg(id order by n) from mock7 where day = 1 and id is not null)
 where title = 'CCN Mock Exam — Day 1 of 7 (200 Questions)';
                               show_answers, show_score, max_warnings, shuffle, all_candidates, attempts_allowed)
select 'CCN Mock Exam — Day 1 of 7 (200 Questions)',
       'Day 1 of 7. This exam has 200 questions covering the full CCN curriculum. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 200 minutes.',
       timestamptz '2026-10-23 08:00:00+01', timestamptz '2026-10-23 18:00:00+01', 200,
       (select array_agg(id order by n) from mock7 where day = 1 and id is not null),
       false, true, 3, true, true, 1
where not exists (select 1 from public.exam_exams where title = 'CCN Mock Exam — Day 1 of 7 (200 Questions)');
