delete from public.questions where source = 'CCN Exam Room Mock — 200 Questions (Oct 2026)' and is_active = false;

-- Check: every row should show 200 and 200. missing_question_numbers lists any question not found.
select d.day,
       (select count(id) from mock7 m where m.day = d.day) as questions_found,
       (select cardinality(question_ids) from public.exam_exams where title = 'CCN Mock Exam — Day ' || d.day || ' of 7 (200 Questions)') as questions_in_exam,
       (select string_agg(n::text, ', ' order by n) from mock7 m where m.day = d.day and m.id is null) as missing_question_numbers
from generate_series(1, 7) as d(day)
order by d.day;

drop table if exists mock7;
